//! Concrete routing evidence, not a classification of all Unicode glyphs.
//! ISO 32000-2 9.6.5.2/4 and 9.8.2; standard names are from Annex D.2.
use pagura_font::{CmapSubtable, FontProgram};
use pagura_text::FontKind;
use std::collections::BTreeSet;

pub(super) fn symbolic(
    program: &FontProgram,
    kind: FontKind,
    latin_encoding: bool,
) -> Option<bool> {
    if kind == FontKind::TrueType {
        let symbol = program.has_cmap_subtable(CmapSubtable::WindowsSymbol);
        let unicode = [
            CmapSubtable::WindowsUnicode,
            CmapSubtable::WindowsUnicodeFull,
            CmapSubtable::Unicode,
        ]
        .into_iter()
        .any(|s| program.has_cmap_subtable(s));
        let mac = program.has_cmap_subtable(CmapSubtable::MacRoman);
        if symbol && !unicode && !mac {
            // A nonsymbolic font can still use the mandated post name route.
            // Its presence makes a character-set inference ambiguous.
            let names = LATIN.iter().any(|n| {
                program
                    .glyph_for_name(n.as_bytes())
                    .is_some_and(|g| g.0 != 0)
            });
            return (!names).then_some(true);
        }
        if !symbol && unicode && latin_encoding {
            return Some(false);
        }
        return None;
    }
    // Only classify a complete small repertoire exposed by its built-in
    // encoding. Unencoded glyphs, aliases and absent names remain ambiguous.
    let encoding = program.builtin_encoding()?;
    let mut glyphs = BTreeSet::new();
    let mut nonlatin = false;
    for name in encoding.iter().flatten() {
        let Some(glyph) = program.glyph_for_name(name.as_bytes()).filter(|g| g.0 != 0) else {
            continue;
        };
        glyphs.insert(glyph);
        nonlatin |= LATIN
            .binary_search_by(|n| n.as_bytes().cmp(name.as_bytes()))
            .is_err();
    }
    (glyphs.len().checked_add(1) == usize::try_from(program.glyph_count()).ok()
        && !glyphs.is_empty())
    .then_some(nonlatin)
}

